window.EXAM_CHAPTER_DATA["west_econ"]["09_宏观经济基本指标"] = {"id":"09_宏观经济基本指标","name":"宏观经济基本指标","kps":[{"id":"KP01","name":"GDP 的含义与核算","file":"教材笔记/06_西方经济学/09_宏观经济基本指标/知识点/KP01_GDP的含义与核算.md","questions":[{"id":"west_econ_09_宏观经济基本指标_KP01_1","num":"1","stem":"下列哪一项应计入当年中国 GDP？","options":{"A":"居民购买二手轿车一辆","B":"面包店购入面粉 1000 元","C":"某外资企业在上海工厂当年生产的手机","D":"政府向退休人员发放养老金 2000 元"},"answer":"C"},{"id":"west_econ_09_宏观经济基本指标_KP01_2","num":"2","stem":"用支出法核算 GDP，下列哪一项不应计入 $G$（政府购买）？","options":{"A":"公务员工资","B":"国防装备采购","C":"政府投资建设高铁","D":"向低收入家庭发放低保"},"answer":"D"},{"id":"west_econ_09_宏观经济基本指标_KP01_3","num":"3","stem":"宏观经济学中的\"投资 $I$\"不包括下列哪一项？","options":{"A":"企业新建厂房","B":"家庭购买新建住宅","C":"企业购买股票","D":"企业存货增加"},"answer":"C"},{"id":"west_econ_09_宏观经济基本指标_KP01_4","num":"4","stem":"用支出法核算一国 GDP 的公式是？","options":{"A":"$Y=C+S+T$","B":"$Y=C+I+G+NX$","C":"$Y=C+I+G$","D":"$Y=W+i+r+\\pi$"},"answer":"B"},{"id":"west_econ_09_宏观经济基本指标_KP01_5","num":"5","stem":"某国当年消费 6000 亿、投资 2000 亿、政府购买 1500 亿、出口 1000 亿、进口 1200 亿，GDP 为？","options":{"A":"10500 亿","B":"9300 亿","C":"9500 亿","D":"11700 亿"},"answer":"B"},{"id":"west_econ_09_宏观经济基本指标_KP01_6","num":"6","stem":"下列关于 GDP 与 GNP（GNI）的说法正确的是？","options":{"A":"GDP 按国民原则，GNP 按国土原则","B":"GDP 按国土原则，GNP 按国民原则","C":"二者口径完全相同","D":"苹果公司在华利润计入中国 GDP，也计入中国 GNP"},"answer":"B"},{"id":"west_econ_09_宏观经济基本指标_KP01_7","num":"7","stem":"生产法核算 GDP 的基本思想是？","options":{"A":"加总所有最终产品销售额","B":"加总各部门增加值（总产出 − 中间投入）","C":"加总所有工资、利息、租金、利润","D":"加总居民所有消费支出"},"answer":"B"},{"id":"west_econ_09_宏观经济基本指标_KP01_8","num":"8","stem":"下列哪一项是 GDP 作为流量指标的正确理解？","options":{"A":"GDP 核算某一时点的国民财富存量","B":"GDP 核算一定时期内新生产的产品价值","C":"GDP 包含历年库存的累积价值","D":"GDP 核算一国居民拥有的全部资产"},"answer":"B"},{"id":"west_econ_09_宏观经济基本指标_KP01_9","num":"9","stem":"【反向】下列哪一项不计入中国当年 GDP？","options":{"A":"中国海尔公司在美国工厂生产的冰箱","B":"北京 SKP 商场当年销售额中的最终消费品","C":"特斯拉上海超级工厂当年生产的汽车","D":"某律师事务所当年提供法律服务收费"},"answer":"A"}]},{"id":"KP02","name":"名义 GDP、实际 GDP 与 GDP 平减指数","file":"教材笔记/06_西方经济学/09_宏观经济基本指标/知识点/KP02_名义GDP与实际GDP.md","questions":[{"id":"west_econ_09_宏观经济基本指标_KP02_1","num":"1","stem":"名义 GDP 与实际 GDP 的根本区别在于？","options":{"A":"是否包含服务","B":"是否按当年价格计算","C":"是否按不变价格计算","D":"是否包含净出口"},"answer":"C"},{"id":"west_econ_09_宏观经济基本指标_KP02_2","num":"2","stem":"GDP 平减指数的计算公式是？","options":{"A":"$\\frac{\\text{名义 GDP}}{\\text{实际 GDP}}\\times100$","B":"$\\frac{\\text{实际 GDP}}{\\text{名义 GDP}}\\times100$","C":"$\\frac{\\text{CPI}}{\\text{PPI}}\\times100$","D":"$\\frac{\\text{当期篮子费用}}{\\text{基期篮子费用}}\\times100$"},"answer":"A"},{"id":"west_econ_09_宏观经济基本指标_KP02_3","num":"3","stem":"某国 2024 年名义 GDP 为 120 万亿，GDP 平减指数为 120（基年=100），实际 GDP 为？","options":{"A":"100 万亿","B":"120 万亿","C":"144 万亿","D":"96 万亿"},"answer":"A"},{"id":"west_econ_09_宏观经济基本指标_KP02_4","num":"4","stem":"名义 GDP 增长 8%，实际 GDP 增长 5%，则 GDP 平减指数上升约？","options":{"A":"3%","B":"13%","C":"15%","D":"2.86%"},"answer":"A"},{"id":"west_econ_09_宏观经济基本指标_KP02_5","num":"5","stem":"以某一年为基年，该年的 GDP 平减指数等于？","options":{"A":"0","B":"100","C":"1","D":"视价格而定"},"answer":"B"},{"id":"west_econ_09_宏观经济基本指标_KP02_6","num":"6","stem":"【反向】下列关于实际 GDP 的说法错误的是？","options":{"A":"实际 GDP 剔除了价格变动影响","B":"实际 GDP 用基年价格计算","C":"实际 GDP 反映一国生产的实物量变化","D":"实际 GDP 等于名义 GDP 乘以 GDP 平减指数"},"answer":"D"},{"id":"west_econ_09_宏观经济基本指标_KP02_7","num":"7","stem":"一国只生产面包，2023 年面包 5 元一个卖 100 个；2024 年面包 6 元一个卖 120 个。以 2023 为基年，2024 年实际 GDP 为？","options":{"A":"600","B":"720","C":"500","D":"620"},"answer":"A"},{"id":"west_econ_09_宏观经济基本指标_KP02_8","num":"8","stem":"【结合现象】2022 年中国 GDP 名义增长 5.2%，实际增长 3.0%，主要说明？","options":{"A":"当年物价水平下降","B":"当年存在通货紧缩","C":"当年 GDP 平减指数有所下降（价格贡献为负）","D":"统计口径错误"},"answer":"C"},{"id":"west_econ_09_宏观经济基本指标_KP02_9","num":"9","stem":"用不变价格计算实际 GDP 的主要目的是？","options":{"A":"简化计算","B":"消除通货膨胀对产出比较的干扰","C":"让 GDP 数字更大","D":"便于税收核算"},"answer":"B"}]},{"id":"KP03","name":"CPI 消费价格指数","file":"教材笔记/06_西方经济学/09_宏观经济基本指标/知识点/KP03_CPI消费价格指数.md","questions":[{"id":"west_econ_09_宏观经济基本指标_KP03_1","num":"1","stem":"CPI 的编制中，\"商品篮子\"的数量权重通常固定在？","options":{"A":"报告期","B":"基期","C":"上一年","D":"当月"},"answer":"B"},{"id":"west_econ_09_宏观经济基本指标_KP03_2","num":"2","stem":"CPI 从 100 涨到 110，则通胀率为？","options":{"A":"110%","B":"10%","C":"11%","D":"9.09%"},"answer":"B"},{"id":"west_econ_09_宏观经济基本指标_KP03_3","num":"3","stem":"下列哪一项不属于 CPI 与 GDP 平减指数的区别？","options":{"A":"CPI 包含进口消费品，平减指数不包含","B":"CPI 篮子固定，平减指数篮子随当期变化","C":"CPI 包含投资品价格，平减指数不包含","D":"CPI 只覆盖消费品，平减指数覆盖所有最终产品"},"answer":"C"},{"id":"west_econ_09_宏观经济基本指标_KP03_4","num":"4","stem":"某篮子基年费用 100 元，现期费用 125 元，则 CPI 为？","options":{"A":"100","B":"125","C":"25","D":"1.25"},"answer":"B"},{"id":"west_econ_09_宏观经济基本指标_KP03_5","num":"5","stem":"【反向】下列哪一项不是 CPI 高估通胀的原因？","options":{"A":"替代偏差","B":"新产品偏差","C":"质量变化偏差","D":"进口品价格下降"},"answer":"D"},{"id":"west_econ_09_宏观经济基本指标_KP03_6","num":"6","stem":"鸡蛋从 5 元涨到 10 元，但消费者改吃鸡肉。CPI 仍按原权重计算鸡蛋价格，这种偏差称为？","options":{"A":"新产品偏差","B":"替代偏差","C":"质量偏差","D":"地点偏差"},"answer":"B"},{"id":"west_econ_09_宏观经济基本指标_KP03_7","num":"7","stem":"【计算】篮子由 5 斤鸡蛋、2 斤苹果组成。2023 年鸡蛋 2 元/斤、苹果 3 元/斤；2024 年鸡蛋 5 元/斤、苹果 8 元/斤。2024 年 CPI 为？","options":{"A":"256.25","B":"41","C":"16","D":"156.25"},"answer":"A"},{"id":"west_econ_09_宏观经济基本指标_KP03_8","num":"8","stem":"核心 CPI 与普通 CPI 的区别在于？","options":{"A":"核心 CPI 不包含食品和能源价格","B":"核心 CPI 只包含食品和能源价格","C":"核心 CPI 不包含服务价格","D":"二者无区别"},"answer":"A"},{"id":"west_econ_09_宏观经济基本指标_KP03_9","num":"9","stem":"【结合现象】2023—2024 年中国 CPI 长期低位，但老百姓感觉生活成本上升，可能原因不包括？","options":{"A":"CPI 篮子权重与高收入群体实际消费结构不匹配","B":"服务价格（教育、医疗、文旅）上涨未充分反映","C":"房价下跌带动居住成本下降拉低 CPI","D":"CPI 数据被人为压低"},"answer":"D"}]},{"id":"KP04","name":"失业的衡量","file":"教材笔记/06_西方经济学/09_宏观经济基本指标/知识点/KP04_失业的衡量.md","questions":[{"id":"west_econ_09_宏观经济基本指标_KP04_1","num":"1","stem":"失业率的正确计算公式是？","options":{"A":"失业人数 / 全部成年人口","B":"失业人数 / 劳动力人数","C":"失业人数 / 就业人数","D":"失业人数 / 退休人口"},"answer":"B"},{"id":"west_econ_09_宏观经济基本指标_KP04_2","num":"2","stem":"下列哪一类人属于\"不属于劳动力\"？","options":{"A":"刚毕业正在投简历的大学生","B":"被裁员后正在找工作的白领","C":"已办理退休手续的老人","D":"被临时解雇等待召回的工人"},"answer":"C"},{"id":"west_econ_09_宏观经济基本指标_KP04_3","num":"3","stem":"某国成年人口 1000 万，就业 600 万，失业 100 万，失业率为？","options":{"A":"10%","B":"14.3%","C":"6.25%","D":"70%"},"answer":"B"},{"id":"west_econ_09_宏观经济基本指标_KP04_4","num":"4","stem":"同上题，劳动力参与率为？","options":{"A":"60%","B":"70%","C":"14.3%","D":"85.7%"},"answer":"B"},{"id":"west_econ_09_宏观经济基本指标_KP04_5","num":"5","stem":"沮丧工人（discouraged worker）是指？","options":{"A":"正在积极找工作的失业者","B":"因找工作无望而退出劳动力市场的人","C":"对工资不满辞职的人","D":"兼职工作者"},"answer":"B"},{"id":"west_econ_09_宏观经济基本指标_KP04_6","num":"6","stem":"【反向】下列关于失业统计的说法错误的是？","options":{"A":"失业者必须在最近 4 周内主动找工作","B":"沮丧工人不计入失业","C":"全职学生算失业","D":"临时请假者算就业"},"answer":"C"},{"id":"west_econ_09_宏观经济基本指标_KP04_7","num":"7","stem":"经济衰退期，大量工人放弃找工作，会使官方失业率？","options":{"A":"上升","B":"下降","C":"不变","D":"无法判断"},"answer":"B"},{"id":"west_econ_09_宏观经济基本指标_KP04_8","num":"8","stem":"【结合现象】中国 2023 年公布的 16—24 岁青年调查失业率峰值约为？","options":{"A":"5.2%","B":"10%","C":"21.3%","D":"30%"},"answer":"C"},{"id":"west_econ_09_宏观经济基本指标_KP04_9","num":"9","stem":"失业人数增加 10 万人，同时劳动力人数不变，失业率将？","options":{"A":"上升","B":"下降","C":"不变","D":"无法判断"},"answer":"A"}]},{"id":"KP05","name":"失业类型与自然失业率","file":"教材笔记/06_西方经济学/09_宏观经济基本指标/知识点/KP05_失业类型与自然失业率.md","questions":[{"id":"west_econ_09_宏观经济基本指标_KP05_1","num":"1","stem":"刚毕业大学生找工作期间的失业属于？","options":{"A":"摩擦性失业","B":"结构性失业","C":"周期性失业","D":"隐性失业"},"answer":"A"},{"id":"west_econ_09_宏观经济基本指标_KP05_2","num":"2","stem":"传统百货公司售货员因电商崛起而失业，且其技能不适应直播带货岗位，这种失业属于？","options":{"A":"摩擦性失业","B":"结构性失业","C":"周期性失业","D":"季节性失业"},"answer":"B"},{"id":"west_econ_09_宏观经济基本指标_KP05_3","num":"3","stem":"2008 年金融危机导致全行业裁员，这种失业属于？","options":{"A":"摩擦性失业","B":"结构性失业","C":"周期性失业","D":"自然失业"},"answer":"C"},{"id":"west_econ_09_宏观经济基本指标_KP05_4","num":"4","stem":"自然失业率等于？","options":{"A":"摩擦性失业 + 周期性失业","B":"结构性失业 + 周期性失业","C":"摩擦性失业 + 结构性失业","D":"周期性失业"},"answer":"C"},{"id":"west_econ_09_宏观经济基本指标_KP05_5","num":"5","stem":"充分就业的含义是？","options":{"A":"失业率为零","B":"周期性失业为零","C":"所有想工作的人都有工作","D":"摩擦性失业为零"},"answer":"B"},{"id":"west_econ_09_宏观经济基本指标_KP05_6","num":"6","stem":"某国摩擦性失业 2%、结构性失业 3%、周期性失业 2.5%，则自然失业率为？","options":{"A":"2%","B":"3%","C":"5%","D":"7.5%"},"answer":"C"},{"id":"west_econ_09_宏观经济基本指标_KP05_7","num":"7","stem":"奥肯定律描述的是？","options":{"A":"通胀与失业的关系","B":"失业率与 GDP 缺口的关系","C":"利率与投资的关系","D":"消费与收入的关系"},"answer":"B"},{"id":"west_econ_09_宏观经济基本指标_KP05_8","num":"8","stem":"【反向】下列关于自然失业率的说法错误的是？","options":{"A":"它是充分就业状态下的失业率","B":"它等于摩擦性失业率 + 结构性失业率","C":"它永远固定不变，约为 5%","D":"它受人口结构、技术进步、制度因素影响"},"answer":"C"},{"id":"west_econ_09_宏观经济基本指标_KP05_9","num":"9","stem":"治理结构性失业的最有效政策是？","options":{"A":"增发货币","B":"扩大政府购买","C":"职业培训与产教融合","D":"降低利率"},"answer":"C"},{"id":"west_econ_09_宏观经济基本指标_KP05_1b","num":"1","stem":"（曲线移动·衔接）GDP 平减指数（价格总水平 P）普遍上升，而名义货币供给 M 不变。这会通过实际货币余额 M/P 影响后续 IS-LM 模型中的哪条曲线？（　）","options":{"A":"LM 曲线左移（实际货币余额减少）","B":"LM 曲线右移","C":"IS 曲线右移","D":"都不移动"},"answer":"A"},{"id":"west_econ_09_宏观经济基本指标_KP05_2b","num":"2","stem":"（曲线移动·衔接）CPI 持续上升意味着生活成本提高，工人在下一轮工资谈判中会要求更高名义工资。这一预期传导到 AD-AS 模型会使哪条曲线移动？（　）","options":{"A":"SAS 短期总供给曲线上移","B":"AD 曲线右移","C":"LAS 右移","D":"都不动"},"answer":"A"}]}]};
